384	    /**
385	     * Reports whether an email's domain is disposable-adjacent: its domain (see
386	     * {@link #emailDomain(String)}) equals one of the known disposable domains (see
387	     * {@link #DISPOSABLE_EMAIL_DOMAINS}) or is a subdomain of one (it ends with {@code '.'} followed
388	     * by a disposable domain), compared case-insensitively. An exact disposable domain is already
389	     * rejected at intake by {@link #normalizeEmail(String)}, so a persisted owner reaches this rule
390	     * only through a subdomain of a disposable domain. An owner without an email has no domain and
391	     * is never disposable-adjacent.
392	     *
393	     * @param email the owner's stored email, or {@code null} when none was supplied
394	     * @return {@code true} when the email's domain is a disposable domain or a subdomain of one
395	     */
396	    private boolean isDisposableAdjacentEmail(String email) {
397	        String domain = emailDomain(email);
398	        if (domain == null) {
399	            return false;
400	        }
401	        return DISPOSABLE_EMAIL_DOMAINS.stream()
402	            .anyMatch(disposable -> domain.equals(disposable) || domain.endsWith("." + disposable));
403	    }
