501	    /**
502	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
503	     * The address is normalized in place (so a required-field check that follows rejects an
504	     * address blank after normalization), the required fields are checked, the telephone and
505	     * email are normalized in place, and the resulting owner is rejected when its derived
506	     * identity key already belongs to another owner. Each rule
507	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
508	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
509	     * to be mapped and saved.
510	     *
511	     * @param ownerFieldsDto the submitted owner fields, normalized in place
512	     */
513	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
514	        applyAddress(ownerFieldsDto);
515	        validateRequiredFields(ownerFieldsDto);
516	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
517	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
518	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
519	        rejectDuplicateIdentity(ownerFieldsDto);
520	        rejectCityAtCapacity(ownerFieldsDto.getCity());
521	        rejectDailyLimitExceeded(registrationDate);
522	    }
