524	    /**
525	     * Applies an owner's address to the submitted fields, normalizing it in place into the
526	     * canonical form stored and returned for the owner. This is the single intake step that owns
527	     * how a submitted address becomes an owner's stored address: it delegates every transform to
528	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
529	     * the results back onto {@code ownerFieldsDto}.
530	     *
531	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
532	     * is present the two structured lines are normalized in place and the flat {@code address} is
533	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
534	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
535	     * every rule that later reads {@code address} sees the structured value. When no structured
536	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
537	     * backward compatibility.
538	     *
539	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
540	     * blank after normalization in either form is rejected by the required-field check that
541	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
542	     * list of named intake steps and gives address handling one place to grow.
543	     *
544	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
545	     */
546	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
547	        String line1 = ownerFieldsDto.getAddressLine1();
548	        if (line1 != null && !line1.isBlank()) {
549	            String normalizedLine1 = normalizeAddress(line1);
550	            ownerFieldsDto.setAddressLine1(normalizedLine1);
551	            String line2 = ownerFieldsDto.getAddressLine2();
552	            if (line2 != null && !line2.isBlank()) {
553	                String normalizedLine2 = normalizeAddress(line2);
554	                ownerFieldsDto.setAddressLine2(normalizedLine2);
555	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
556	            } else {
557	                ownerFieldsDto.setAddressLine2(null);
558	                ownerFieldsDto.setAddress(normalizedLine1);
559	            }
560	        } else {
561	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
562	        }
563	    }
