565	    /**
566	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
567	     * falls on a business day. The date supplied on the request is used when present, otherwise the
568	     * server's current date is used. When that effective date lands on a Saturday, Sunday or listed
569	     * public holiday it is rolled forward to the next non-holiday business day; a non-holiday weekday
570	     * is left unchanged. This single adjusted date
571	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
572	     * membership number's year segment, the per-day create limit) is computed against.
573	     *
574	     * A supplied registration date later than the server's current date is rejected with an
575	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
576	     *
577	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
578	     * @return the effective registration date rolled forward to the next business day
579	     */
580	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
581	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
582	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
583	            throw new InvalidFieldsException(List.of("registrationDate"));
584	        }
585	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
586	        return toBusinessDay(effective);
587	    }
588	
589	    /**
590	     * The fixed public holidays the business-day roll skips. A date landing on any of these is
591	     * advanced, along with weekends, until it reaches the next non-holiday business day.
592	     */
593	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
594	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
595	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
596	        LocalDate.parse("2026-12-28"));
597	
598	    /**
599	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public holiday is
600	     * advanced one day at a time until it reaches a weekday that is not a public holiday, while a
601	     * date already on such a business day is returned unchanged.
602	     *
603	     * @param date the date to adjust
604	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
605	     */
606	    private LocalDate toBusinessDay(LocalDate date) {
607	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
608	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
609	                || PUBLIC_HOLIDAYS.contains(date)) {
610	            date = date.plusDays(1);
611	        }
612	        return date;
613	    }
