615	    /**
616	     * The maximum number of owners that may be created on a single day. Once this many owners
617	     * already carry today's {@code registrationDate}, no further owner may be created today.
618	     */
619	    private static final long DAILY_OWNER_LIMIT = 100L;
620	
621	    /**
622	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
623	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
624	     * date the new owner would be stored with, so owners are capped per business day. When the limit
625	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
626	     * advice renders as a 429 Too Many Requests response.
627	     *
628	     * @param registrationDate the adjusted business-day registration date of the owner being created
629	     */
630	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
631	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
632	            throw new DailyOwnerLimitExceededException(registrationDate);
633	        }
634	    }
