636	    /**
637	     * Counts the existing owners whose adjusted business-day {@code registrationDate} equals the
638	     * given date. This is the single definition of the per-day owner count, shared by the per-day
639	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
640	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
641	     *
642	     * @param registrationDate the adjusted business-day registration date to count owners against
643	     * @return the number of existing owners carrying that registration date
644	     */
645	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
646	        return this.clinicService.findAllOwners().stream()
647	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
648	            .count();
649	    }
