651	    /**
652	     * The number of owners that may carry a single day's {@code registrationDate} before that day
653	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
654	     * the create and read responses report {@code bulkSignupWarning} true for that date.
655	     */
656	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
657	
658	    /**
659	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
660	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
661	     * count is taken against the same adjusted date owners are stored with, mirroring the
662	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
663	     *
664	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
665	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
666	     */
667	    private boolean bulkSignupWarning(LocalDate registrationDate) {
668	        if (registrationDate == null) {
669	            return false;
670	        }
671	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
672	    }
