674	    /**
675	     * The maximum number of owners a single city may hold. Once a city already contains this
676	     * many owners, no further owner may be created in it.
677	     */
678	    private static final long CITY_OWNER_CAPACITY = 50L;
679	
680	    /**
681	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
682	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
683	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
684	     * which the exception advice renders as a 409 Conflict response.
685	     *
686	     * @param city the city of the owner being created
687	     */
688	    private void rejectCityAtCapacity(String city) {
689	        if (countOwnersInCity(city) >= CITY_OWNER_CAPACITY) {
690	            throw new CityCapacityExceededException(city);
691	        }
692	    }
