694	    /**
695	     * Counts the existing owners whose {@code city} equals the given city, compared
696	     * case-insensitively. This is the single definition of the per-city owner count, shared by the
697	     * hard capacity rejection ({@link #rejectCityAtCapacity(String)}) and the approaching-capacity
698	     * warning ({@link #capacityWarning(String)}), so both measure a city's occupancy identically.
699	     *
700	     * @param city the city to count owners against
701	     * @return the number of existing owners whose city matches
702	     */
703	    private long countOwnersInCity(String city) {
704	        return this.clinicService.findAllOwners().stream()
705	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
706	            .count();
707	    }
