758	    /**
759	     * Ensures the computed {@code memberId} is unique across existing owners. When the given base id
760	     * collides with an existing owner's {@code memberId}, {@code '-<n>'} is appended with the smallest
761	     * {@code n} of 2 or more that yields an id no existing owner already carries.
762	     *
763	     * @param baseCode the member id computed for the owner being created
764	     * @return the base id when it is already unique, otherwise the de-duplicated id
765	     */
766	    private String deduplicateMemberId(String baseCode) {
767	        Set<String> existing = this.clinicService.findAllOwners().stream()
768	            .map(Owner::getMemberId)
769	            .filter(Objects::nonNull)
770	            .collect(Collectors.toSet());
771	        if (!existing.contains(baseCode)) {
772	            return baseCode;
773	        }
774	        int n = 2;
775	        while (existing.contains(baseCode + "-" + n)) {
776	            n++;
777	        }
778	        return baseCode + "-" + n;
779	    }
