798	    /**
799	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
800	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it does not share
801	     * an existing owner's identity key. A member that declared its household via
802	     * {@code sharesHousehold} is a deliberate addition to a known household, not a suspected
803	     * duplicate, so it is never flagged. Otherwise it is a possible duplicate when an existing owner
804	     * shares the Soundex code of its {@code lastName} and its {@code postcode} while carrying a
805	     * different identity key (see {@link #findPossibleDuplicate(Owner)}). When such an owner is
806	     * found, {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to the
807	     * matching owner's id; otherwise {@code possibleDuplicate} is set {@code false} and no matching
808	     * id is recorded. An owner without a postcode can share no postcode and is never a possible
809	     * duplicate.
810	     *
811	     * @param owner the owner being created, already carrying its normalized telephone and postcode
812	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
813	     */
814	    private void applyPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
815	        owner.setPossibleDuplicate(false);
816	        owner.setPossibleDuplicateOf(null);
817	        if (sharesHousehold(ownerFieldsDto)) {
818	            return;
819	        }
820	        findPossibleDuplicate(owner).ifPresent(existing -> {
821	            owner.setPossibleDuplicate(true);
822	            owner.setPossibleDuplicateOf(existing.getId());
823	        });
824	    }
