826	    /**
827	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
828	     * duplicate: a non-deleted owner whose {@code lastName} shares the new owner's Soundex code (see
829	     * {@link Owner#soundex(String)}) and whose {@code postcode} matches, while carrying a different
830	     * identity key (see {@link Owner#identityKey(String, String, String)}). Requiring a differing
831	     * identity key keeps a hard duplicate — already rejected with 409 by
832	     * {@link #rejectDuplicateIdentity(OwnerFieldsDto)} — from also being flagged as a soft match, so
833	     * the two household members whose telephones differ (hence differing identity keys, but matching
834	     * Soundex and postcode) are exactly the soft matches surfaced here. This is the single definition
835	     * of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records
836	     * the outcome on the owner. An owner without a postcode can share no postcode and matches nothing,
837	     * so {@link java.util.Optional#empty()} is returned.
838	     *
839	     * @param owner the owner being created, already carrying its normalized telephone and postcode
840	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
841	     */
842	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
843	        if (owner.getPostcode() == null) {
844	            return java.util.Optional.empty();
845	        }
846	        String soundex = Owner.soundex(owner.getLastName());
847	        String identityKey = owner.getIdentityKey();
848	        return this.clinicService.findAllOwners().stream()
849	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
850	            .filter(existing -> !identityKey.equals(existing.getIdentityKey())
851	                && soundex.equals(Owner.soundex(existing.getLastName()))
852	                && owner.getPostcode().equals(existing.getPostcode()))
853	            .findFirst();
854	    }
