883	    /**
884	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
885	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
886	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
887	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
888	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
889	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
890	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
891	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
892	     *
893	     * @param telephone the submitted telephone value
894	     * @return the normalized E.164 telephone
895	     */
896	    private String normalizeTelephone(String telephone) {
897	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
898	        String e164;
899	        if (cleaned.startsWith("+")) {
900	            e164 = "+" + cleaned.substring(1);
901	        } else {
902	            String national = cleaned;
903	            if (national.startsWith("0")) {
904	                national = national.substring(1);
905	            }
906	            e164 = "+61" + national;
907	        }
908	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
909	            throw new InvalidFieldsException(List.of("telephone"));
910	        }
911	        validateNationalNumberLength(e164);
912	        return e164;
913	    }
