915	    /**
916	     * Validates the national-number length of an already syntactically valid E.164 telephone
917	     * against its country code. When the number carries a country code this application recognizes
918	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
919	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
920	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
921	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
922	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
923	     * that is not recognized carries no per-country length rule and is left to the general
924	     * 8-to-15-digit E.164 check.
925	     *
926	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
927	     */
928	    private void validateNationalNumberLength(String e164) {
929	        String countryCode = Owner.countryCodeOf(e164);
930	        if (countryCode == null) {
931	            return;
932	        }
933	        int nationalLength = e164.length() - 1 - countryCode.length();
934	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
935	            throw new InvalidFieldsException(List.of("telephone"));
936	        }
937	    }
