939	    /**
940	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
941	     * and a domain containing at least one dot, none of the parts holding whitespace or a
942	     * second {@code @}.
943	     */
944	    private static final java.util.regex.Pattern EMAIL_PATTERN =
945	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
946	
947	    /**
948	     * Disposable email domains an owner may not register with. An email whose domain (compared
949	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
950	     */
951	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
952	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
953	
954	    /**
955	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
956	     * accepted and returned unchanged. When present it must be a syntactically valid address
957	     * whose domain is not on the disposable-domain blocklist (see
958	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
959	     * present but syntactically invalid or on a disposable domain an
960	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
961	     * response naming the {@code email} field.
962	     *
963	     * @param email the submitted email value, or {@code null} when omitted
964	     * @return the lower-cased email, or {@code null} when none was supplied
965	     */
966	    private String normalizeEmail(String email) {
967	        if (email == null) {
968	            return null;
969	        }
970	        String trimmed = email.trim();
971	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
972	            throw new InvalidFieldsException(List.of("email"));
973	        }
974	        String domain = emailDomain(trimmed);
975	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
976	            throw new InvalidFieldsException(List.of("email"));
977	        }
978	        return canonicalEmail(trimmed);
979	    }
