981	    /**
982	     * Reduces an email to the canonical form used both to store it and to compare it against
983	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
984	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
985	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
986	     * value read back off an existing owner without risk of rejecting it. This is the single
987	     * definition of email identity: two emails denote the same address exactly when they
988	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
989	     * an email already on an existing owner can be compared for equality after both pass through
990	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
991	     *
992	     * @param email the email to canonicalize, or {@code null} when none was supplied
993	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
994	     */
995	    private String canonicalEmail(String email) {
996	        if (email == null) {
997	            return null;
998	        }
999	        return email.trim().toLowerCase(java.util.Locale.ROOT);
1000	    }
