1024	    /**
1025	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
1026	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
1027	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
1028	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
1029	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
1030	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
1031	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
1032	     * 400 response naming the {@code postcode} field.
1033	     *
1034	     * @param postcode the submitted postcode, or {@code null} when omitted
1035	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
1036	     */
1037	    private void validatePostcode(String postcode, String city) {
1038	        if (postcode == null) {
1039	            return;
1040	        }
1041	        if (!postcode.matches("^[0-9]{4}$")) {
1042	            throw new InvalidFieldsException(List.of("postcode"));
1043	        }
1044	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
1045	        if (range != null) {
1046	            int value = Integer.parseInt(postcode);
1047	            if (value < range[0] || value > range[1]) {
1048	                throw new InvalidFieldsException(List.of("postcode"));
1049	            }
1050	        }
1051	    }
