1053	    /**
1054	     * Rejects a new owner that is an exact identity duplicate of an existing owner. An owner's
1055	     * identity is its single derived identity key (see
1056	     * {@link Owner#identityKey(String, String, String)}) — the SHA-256 hex digest over its
1057	     * normalized {@code telephone}, canonical {@code email} and the Soundex code of its
1058	     * {@code lastName} — so a new owner is a hard duplicate only when some existing, non-deleted
1059	     * owner carries the same identity key. The email-domain blocklist has already been applied when
1060	     * the email was normalized ahead of this check, so a disposable-domain email is rejected before
1061	     * duplicate detection runs. Two owners that merely belong to the same household (the same last
1062	     * name and postcode) but carry different telephones now have distinct identity keys and are not
1063	     * rejected here; such a near-match is instead recorded as a soft {@code possibleDuplicate} (see
1064	     * {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)}). When an existing owner shares the new
1065	     * owner's identity key a {@link DuplicateIdentityException} is thrown, which the exception advice
1066	     * renders as a 409 Conflict response. Setting {@code sharesHousehold} declares the owner a
1067	     * deliberate household member and bypasses this block.
1068	     *
1069	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
1070	     */
1071	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
1072	        if (sharesHousehold(ownerFieldsDto)) {
1073	            return;
1074	        }
1075	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
1076	            ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
1077	        boolean taken = this.clinicService.findAllOwners().stream()
1078	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
1079	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
1080	        if (taken) {
1081	            throw new DuplicateIdentityException(identityKey);
1082	        }
1083	    }
