1180	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
1181	            .collect(Collectors.toList());
1182	    }
1183	
1184	    /**
1185	     * Counts the owners that belong to the household identified by the given {@code householdId} (see
1186	     * {@link #householdMembers(String)}), i.e. every owner carrying that exact identifier. The count
1187	     * is taken against the current set of owners, so after a create it reflects the household's size
1188	     * including the newly persisted owner. An owner without a household (a {@code null} identifier)
1189	     * belongs to no shared household and yields {@code 0}.
1190	     *
1191	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
1192	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
1193	     */
1194	    private int countHouseholdMembers(String householdId) {
1195	        return householdMembers(householdId).size();
1196	    }
1197	
1198	    /**
1199	     * Stamps an owner with its household member count, the number of owners sharing its household
1200	     * (see {@link #countHouseholdMembers(String)}), so every value the owner derives from its
1201	     * household size (its membership factor and level) reads a populated count rather than the
1202	     * unstamped default. This is the single definition of hydrating an owner with its household
1203	     * member count, shared by the create and read paths that render an owner's derived values.
1204	     *
1205	     * @param owner the owner to stamp, mutated in place with its household member count
1206	     */
1207	    private void applyHouseholdMemberCount(Owner owner) {
1208	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
1209	    }
1210	
1211	    /**
1212	     * Resolves the household level ceiling a newly created owner is subject to: one above the
1213	     * current maximum {@code membershipLevel} among the existing, non-deleted owners already
1214	     * sharing its household (see {@link #householdMembers(String)}). Each existing member is
1215	     * stamped with its household member count first so its {@link Owner#getMembershipLevel()}
1216	     * reads a populated count, mirroring how the create and read paths render a member's derived
1217	     * level. The ceiling is taken before the new owner is persisted, so it reflects only the
1218	     * members already in the household. When the owner joins an empty household — no household
1219	     * identifier, or no existing member — no ceiling applies and {@code null} is returned, letting
1220	     * the owner earn its uncapped level (see {@link Owner#cappedMembershipLevel(int, Integer)}).
1221	     *
1222	     * @param householdId the shared household identifier of the owner being created, or {@code null}
1223	     * @return one above the household's current maximum membership level, or {@code null} when no ceiling applies
1224	     */
1225	    private Integer householdMembershipLevelCap(String householdId) {
1226	        java.util.OptionalInt max = householdMembers(householdId).stream()
1227	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
1228	            .peek(this::applyHouseholdMemberCount)
1229	            .mapToInt(Owner::getMembershipLevel)
1230	            .max();
1231	        return max.isPresent() ? max.getAsInt() + 1 : null;
1232	    }
1233	
1234	    /**
1235	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
1236	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
1237	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
1238	     *
1239	     * @param value the value to collapse, or {@code null}
1240	     * @return the whitespace-collapsed value, never {@code null}
1241	     */
1242	    private String collapseWhitespace(String value) {
1243	        if (value == null) {
1244	            return "";
1245	        }
1246	        return value.trim().replaceAll("\\s+", " ");
1247	    }
1248	
1249	    /**
1250	     * Common street-type abbreviations expanded during address normalization, keyed by their
1251	     * upper-cased token.
1252	     */
1253	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
1254	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
1255	
1256	    /**
1257	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
1258	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
1259	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
1260	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
1261	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
1262	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
1263	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
1264	     * everywhere an address is stored or compared.
1265	     *
1266	     * @param address the submitted address value, or {@code null}
1267	     * @return the normalized address, never {@code null}
1268	     */
1269	    private String normalizeAddress(String address) {
1270	        if (address == null) {
1271	            return "";
1272	        }
1273	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
1274	        if (collapsed.isEmpty()) {
1275	            return "";
1276	        }
1277	        String[] tokens = collapsed.split(" ");
1278	        StringBuilder sb = new StringBuilder(collapsed.length());
1279	        for (int i = 0; i < tokens.length; i++) {
1280	            if (i > 0) {
1281	                sb.append(' ');
1282	            }
1283	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1284	        }
1285	        return sb.toString();
1286	    }
1287	}
